I think that something like this (I have not tested it yet) could solve the issue. It uses a secondary zero-based indexing.
Do you think this could work?

```
void ActionImpl::set_actuator_async(const int index, const float value,
                                    const Action::ResultCallback& callback) {
  MavlinkCommandSender::CommandLong command{};

  auto zbIndex = index - 1;  // zero-based index
  if (zbIndex >= 0) {
    command.command = MAV_CMD_DO_SET_ACTUATOR;
    command.target_component_id = _system_impl->get_autopilot_id();

    switch (zbIndex % 6) {
      case 0:
        command.params.maybe_param1 = value;
        break;
      case 1:
        command.params.maybe_param2 = value;
        break;
      case 2:
        command.params.maybe_param3 = value;
        break;
      case 3:
        command.params.maybe_param4 = value;
        break;
      case 4:
        command.params.maybe_param5 = value;
        break;
      case 5:
        command.params.maybe_param6 = value;
        break;
    }
    command.params.maybe_param7 = static_cast<float>(zbIndex) / 6.0f;

    _system_impl->send_command_async(
        command, [this, callback](MavlinkCommandSender::Result result, float) {
          command_result_callback(result, callback);
        });
  }
}
```

